using System.Collections.Generic;
using UnityEngine;

public static class Level
{
	public static Transform levelContainer;

	public static Vector2 startPosition;

	public static Vector2 exitPosition;

	public static Vector2 itemStorePortalOutPosition;

	public static Vector2 itemStorePortalInPosition;

	public static Vector2 skillStorePortalOutPosition;

	public static Vector2 skillStorePortalInPosition;

	public static Vector2 miscRoomPortalOutPosition;

	public static Vector2 miscRoomPortalInPosition;

	public static bool exitFound;

	public static bool itemStoreFound;

	public static bool skillStoreFound;

	public static bool miscRoomFound;

	public static bool removeAllPits = false;

	public static bool resetUsedRooms = true;

	public static bool doubleEnemies = false;

	public static bool isBossRushMode = false;

	public static Dictionary<Compass.CompassIndicatorType, CompassIndicatorTrigger> ctDict = new Dictionary<Compass.CompassIndicatorType, CompassIndicatorTrigger>();

	public static bool compassTriggered = false;

	public static Compass.CompassIndicatorType miscType = Compass.CompassIndicatorType.MiscRoom;

	public static TileGrid tileGrid;

	public static Vector2 minTileGridPosition;

	public static Vector2 maxTileGridPosition;

	public static string tileSetName;

	public static ElementType element = ElementType.Neutral;

	public static ElementType prevElement = ElementType.Neutral;

	private static Dictionary<string, Room> loadedRoomDict;

	private static List<Tuple<TileGridSection, Room>> gridRoomTupleList;

	private static List<Tuple<TileGridSection, Room>> gridHallTupleList;

	private static List<Room> currentRoomList;

	private static List<Room> currentHallList;

	public static int totalEnemyCount;

	public static int enemiesDefeatedCount;

	public static Vector2 AvgTileGridPosition => (minTileGridPosition + maxTileGridPosition) * 0.5f;

	public static Dictionary<string, Room> LoadedRoomDict => loadedRoomDict ?? (loadedRoomDict = new Dictionary<string, Room>());

	public static List<Tuple<TileGridSection, Room>> GridRoomTupleList => gridRoomTupleList ?? (gridRoomTupleList = new List<Tuple<TileGridSection, Room>>());

	public static List<Tuple<TileGridSection, Room>> GridHallTupleList => gridHallTupleList ?? (gridHallTupleList = new List<Tuple<TileGridSection, Room>>());

	public static List<Room> CurrentRoomList => currentRoomList ?? (currentRoomList = new List<Room>());

	public static List<Room> CurrentHallList => currentHallList ?? (currentHallList = new List<Room>());

	public static float EnemyDefeatedPercentage => (!isBossRushMode && totalEnemyCount > 0) ? Mathf.Clamp01((float)enemiesDefeatedCount / (float)totalEnemyCount) : 1f;

	public static void ClearRoomPositions()
	{
		exitFound = false;
		itemStoreFound = false;
		itemStorePortalInPosition = Vector2.zero;
		itemStorePortalOutPosition = Vector2.zero;
		skillStoreFound = false;
		skillStorePortalInPosition = Vector2.zero;
		skillStorePortalOutPosition = Vector2.zero;
		miscRoomFound = false;
		miscRoomPortalOutPosition = Vector2.zero;
		miscRoomPortalInPosition = Vector2.zero;
		compassTriggered = false;
	}
}
