	public static void SetStartPosition()
	{
		Vector2 startPosition = Level.startPosition;
		Player[] playerScripts = GameController.playerScripts;
		foreach (Player player in playerScripts)
		{
			if (!(player == null))
			{
				player.transform.position = startPosition;
				player.myOrigin = startPosition;
				player.lastCheckpoint = player.myOrigin;
				player.facingDirection = FacingDirection.Down;
				player.anim.Play("IdleDown");
			}
		}
		Camera.main.transform.position = new Vector3(startPosition.x, startPosition.y, -10f);
	}

	public static void SetExitAndStorePositions()
	{
		foreach (Tuple<TileGridSection, Room> gridRoomTuple in Level.GridRoomTupleList)
		{
			Room second = gridRoomTuple.Second;
			switch (second.type)
			{
			case RoomType.Exit:
				Level.exitPosition = second.transform.Find("Enemies/ExitRoomEventHandler").position;
				break;
			case RoomType.ItemStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.itemStorePortalInPosition = transform.Find("Spawn").position;
				Level.itemStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.SkillStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.skillStorePortalInPosition = transform.Find("Spawn").position;
				Level.skillStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.Misc:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.miscRoomPortalInPosition = transform.Find("Spawn").position;
				Level.miscRoomPortalOutPosition = transform.Find("Exit").position;
				break;
			}
			}
		}
		Level.miscRoomFound = (Level.skillStoreFound = (Level.itemStoreFound = (Level.exitFound = Level.isBossRushMode)));
	}

	public static void SetMinMaxPositions()
	{
		TileGrid tileGrid = Level.tileGrid;
		int rowCount = Level.tileGrid.RowCount;
		int colCount = Level.tileGrid.ColCount;
		Vector2 vector = new Vector2((float)rowCount * 0.5f, (float)colCount * 0.5f);
		Vector2 vector2 = vector;
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				if (tileGrid[i, j] != null)
				{
					if ((float)i < vector.x)
					{
						vector.x = i;
					}
					else if ((float)i > vector2.x)
					{
						vector2.x = i;
					}
					if ((float)j < vector.y)
					{
						vector.y = j;
					}
					else if ((float)j > vector2.y)
					{
						vector2.y = j;
					}
				}
			}
		}
		Level.minTileGridPosition = new Vector2(vector.y, 0f - vector.x);
		Level.maxTileGridPosition = new Vector2(vector2.y, 0f - vector2.x);
	}

	private static void UpdateLoadingScreenMessage()
	{
		loadingScreenMsgInactive += loadingScreenMsgActive;
		loadingScreenMsgActive = "\n" + TextManager.GetUIText("loadingScreen-generation" + loadingScreenMsgIndex);
		loadingScreenMsgIndex++;
		GameController.loadingScreen.SetProgressText(loadingScreenMsgInactive + "</color>" + loadingScreenMsgActive + " ...");
	}
}

using System.Collections.Generic;
using UnityEngine;

public static class MeshGenerator
{
	public static void GenerateMeshes(TileGrid tileGrid, Transform parentTrans = null, string forceTileSet = "", bool createChildContainer = true)
	{
		GameObject gameObject = parentTrans.gameObject;
		if (createChildContainer)
		{
			gameObject = Globals.FindOrCreateGameObject("Meshes", parentTrans);
			parentTrans = gameObject.transform;
		}
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < Tile.tileLayerNames.Length; i++)
		{
			Tuple<MeshFilter, MeshRenderer> tuple = CreateLayerMeshObj(Tile.tileLayerNames[i], parentTrans);
			Tuple<Mesh, Material[]> tuple2 = CreateLayerMesh(tileGrid, Tile.tileLayerNames[i], forceTileSet);
			tuple.First.sharedMesh = tuple2.First;
			tuple.Second.materials = tuple2.Second;
			list.Add(tuple.Second.gameObject);
		}
		StaticBatchingUtility.Combine(list.ToArray(), parentTrans.gameObject);
	}

	public static Tuple<Mesh, Material[]> CreateLayerMesh(TileGrid tileGrid, string tileLayerName, string forceTileSet = "")
	{
		Mesh mesh = new Mesh();
		Dictionary<string, List<int>> dictionary = new Dictionary<string, List<int>>();
		mesh.vertices = tileGrid.layerVertexData[tileLayerName].vertices;
		mesh.triangles = InitTriangles(mesh.vertices.Length / 4);
		mesh.normals = InitNormals(mesh.vertices.Length);
		mesh.uv = InitUVs(tileGrid, tileLayerName, forceTileSet);
		mesh.colors = InitColors(mesh.vertices.Length, tileGrid, tileLayerName);
		InitSubMeshTriangles(tileGrid.layerVertexData[tileLayerName].subMeshIndices, dictionary);
		List<Material> list = new List<Material>();
		mesh.subMeshCount = tileGrid.layerVertexData[tileLayerName].tileSetNames.Count;
		int num = 0;
		foreach (string tileSetName in tileGrid.layerVertexData[tileLayerName].tileSetNames)
		{
			mesh.SetTriangles(dictionary[tileSetName].ToArray(), num);
			list.Add(TileSet.GetTileSet(tileSetName).material);
			num++;
		}
		return new Tuple<Mesh, Material[]>(mesh, list.ToArray());
	}

	public static Tuple<MeshFilter, MeshRenderer> CreateLayerMeshObj(string tileLayerName, Transform parentTrans)
	{
		GameObject gameObject = Globals.FindOrCreateGameObject(tileLayerName, parentTrans);
		MeshFilter meshFilter = gameObject.GetComponent<MeshFilter>();
		if (meshFilter == null)
		{
			meshFilter = gameObject.AddComponent<MeshFilter>();
		}
		if (meshFilter.sharedMesh != null)
		{
			meshFilter.sharedMesh.Clear();
		}
		MeshRenderer meshRenderer = gameObject.GetComponent<MeshRenderer>();
		if (meshRenderer == null)
		{
			meshRenderer = gameObject.AddComponent<MeshRenderer>();
		}
		switch (tileLayerName)
		{
		case "Floor":
			meshRenderer.sortingLayerName = "Default";
			break;
		case "Pit":
			meshRenderer.sortingLayerName = "SubFloor";
			meshRenderer.gameObject.layer = LayerMask.NameToLayer("Pit");
			break;
		case "Debug":
			meshRenderer.sortingLayerName = "UI";
			break;
		default:
			meshRenderer.sortingLayerName = tileLayerName;
			break;
		}
		return new Tuple<MeshFilter, MeshRenderer>(meshFilter, meshRenderer);
	}

	public static int[] InitTriangles(int tileCount, int indexOffset = 0)
	{
		int[] array = new int[tileCount * 3 * 2];
		int num = indexOffset;
		for (int i = 0; i < tileCount; i++)
		{
			array[i * 6] = num;
			array[i * 6 + 1] = num + 1;
			array[i * 6 + 2] = num + 2;
			array[i * 6 + 3] = num + 2;
			array[i * 6 + 4] = num + 1;
			array[i * 6 + 5] = num + 3;
			num += 4;
		}
		return array;
	}

	public static void InitSubMeshTriangles(Dictionary<string, List<int>> subMeshIndices, Dictionary<string, List<int>> subMeshTriangles)
	{
		foreach (KeyValuePair<string, List<int>> subMeshIndex in subMeshIndices)
		{
			for (int i = 0; i < subMeshIndex.Value.Count; i++)
			{
				if (!subMeshTriangles.ContainsKey(subMeshIndex.Key))
				{
					subMeshTriangles[subMeshIndex.Key] = new List<int>();
				}
				subMeshTriangles[subMeshIndex.Key].AddRange(InitTriangles(1, subMeshIndex.Value[i]));
			}
		}
	}

	public static Vector2[] InitUVs(TileGrid tileGrid, string tileLayerName, string forceTileSet = "")
	{
		List<Vector2> list = new List<Vector2>();
		for (int i = 0; i < tileGrid.RowCount; i++)
		{
			for (int j = 0; j < tileGrid.ColCount; j++)
			{
				if (!TileGrid.SkipTile(tileGrid[i, j], tileLayerName))
				{
					Tile tile = tileGrid[i, j];
					TileSet tileSet = ((!(forceTileSet != string.Empty)) ? TileSet.GetTileSet(tile.layers[tileLayerName].tileSetName) : TileSet.GetTileSet(forceTileSet));
					Vector2 tilePositionInGrid = tileSet.GetTilePositionInGrid(tile, tileLayerName, i, j, tileGrid);
					Vector2[] array = tileSet.GetUVFromTilePosition(tilePositionInGrid);
					if (tile.layers[tileLayerName].flipX)
					{
						array = new Vector2[4]
						{
							array[2],
							array[3],
							array[0],
							array[1]
						};
					}
					if (tile.layers[tileLayerName].flipY)
					{
						array = new Vector2[4]
						{
							array[1],
							array[0],
							array[3],
							array[2]
						};
					}
					list.AddRange(array);
				}
			}
		}
		return list.ToArray();
	}

	public static Vector3[] InitNormals(int vertexCount)
	{
		Vector3[] array = new Vector3[vertexCount];
		for (int i = 0; i < vertexCount; i++)
		{
			ref Vector3 reference = ref array[i];
			reference = Vector3.back;
		}
		return array;
	}

	public static Color[] InitColors(int vertexCount, TileGrid tileGrid, string tileLayerName)
	{
		Color[] array = new Color[vertexCount];
		for (int i = 0; i < vertexCount; i++)
		{
			ref Color reference = ref array[i];
			reference = new Color(1f, 1f, 1f);
		}
		if (tileLayerName != "Overlay")
		{
			return array;
		}
		int num = 0;
		Color color = new Color(1f, 1f, 1f, 0.66f);
		for (int j = 0; j < tileGrid.RowCount; j++)
		{
			for (int k = 0; k < tileGrid.ColCount; k++)
			{
				Tile tile = tileGrid[j, k];
				if (!TileGrid.SkipTile(tile, tileLayerName))
				{
					num++;
					if (tile.overlay == Tile.OverlayType.BottomWall || tile.overlay == Tile.OverlayType.TopLeftWall || tile.overlay == Tile.OverlayType.TopRightWall)
					{
						int num2 = (num - 1) * 4;
						array[num2 + 2] = color;
						array[num2] = color;
						ref Color reference2 = ref array[num2 + 3];
						reference2 = Color.white;
						ref Color reference3 = ref array[num2 + 1];
						reference3 = Color.white;
					}
				}
			}
		}
		return array;
	}
