	public TMXFile(string fileName)
	{
		string text = fileName;
		if (!fileName.Contains("Assets/"))
		{
			text = "Assets/" + fileName;
		}
		if (!text.EndsWith(".xml"))
		{
			text += ".xml";
		}
		TextAsset textAsset = ChaosBundle.Get<TextAsset>(text);
		if (textAsset == null)
		{
			Debug.Log("Unable to load TMX file at: " + text);
			return;
		}
		TMXData = textAsset.text;
		tileSets = new Dictionary<string, TileSet>();
	}
	public bool ParseData()
	{
		if (TMXData == null)
		{
			return false;
		}
		layerDict = new Dictionary<string, XmlNode>();
		XmlDocument xmlDocument = new XmlDocument();
		xmlDocument.Load(new StringReader(TMXData));
		XmlNodeList childNodes = xmlDocument.DocumentElement.ChildNodes;
		foreach (XmlNode item in childNodes)
		{
			switch (item.Name)
			{
			case "tileset":
				ParseTileSetData(item);
				break;
			case "layer":
			{
				string innerText = item.Attributes["name"].InnerText;
				if (Array.IndexOf(ValidLayerNames, innerText) >= 0)
				{
					layerDict[innerText] = item;
				}
				break;
			}
			}
		}
		if (!CheckLayersAndTileSets())
		{
			return false;
		}
		string[] validLayerNames = ValidLayerNames;
		foreach (string layerName in validLayerNames)
		{
			ParseLayer(layerName);
		}
		return true;
	}
	public bool CheckLayersAndTileSets()
	{
		if (!layerDict.ContainsKey("Terrain") || !layerDict.ContainsKey("Connections"))
		{
			Debug.Log("Background layer or Connections layer not found in TMX file! Aborting import");
			return false;
		}
		if (!tileSets.ContainsKey("MetaDataTileSet"))
		{
			Debug.Log("MetaDataTileSet not found in TMX file! Aborting import");
			return false;
		}
		if (tileSets.Keys.Count < 2)
		{
			Debug.Log("Only 1 TileSet found! Must have at least the MetaDataTileSet and a main TileSet to use on the Background layer. Aborting import");
			return false;
		}
		if (tileSets.Keys.Count > 2)
		{
			Debug.Log("More than 2 TileSets found! Only expecting the MetaDataTileSet and another for the Background layer. Aborting import");
			return false;
		}
		return true;
	}
	public void ParseLayer(string layerName)
	{
		XmlNode xmlNode = layerDict[layerName];
		XmlNode xmlNode2 = xmlNode.SelectSingleNode("data");
		int num = int.Parse(xmlNode.Attributes["width"].InnerText);
		int num2 = int.Parse(xmlNode.Attributes["height"].InnerText);
		if (tileMap == null)
		{
			tileMap = new Tile[num2, num];
		}
		string[] array = xmlNode2.InnerText.Split(',');
		int num3 = 0;
		for (int i = 0; i < num2; i++)
		{
			string text = string.Empty;
			for (int j = 0; j < num; j++)
			{
				int num4 = Convert.ToInt32(array[num3]);
				num4++;
				switch (layerName)
				{
				case "Terrain":
					num4 -= tileSets["MetaDataTileSet"].firstID;
					ParseTerrainLayer(xmlNode, i, j, num4);
					break;
				case "Connections":
					num4 -= tileSets["MetaDataTileSet"].firstID;
					ParseConnectionsLayer(xmlNode, i, j, num4);
					text += tileMap[i, j];
					break;
				}
				num3++;
			}
		}
	}
	public void ParseTerrainLayer(XmlNode outerNode, int tileMapRow, int tileMapCol, int tileSetID)
	{
		if (tileSetID <= 0 || !tileSets["MetaDataTileSet"].metaData.ContainsKey(tileSetID))
		{
