		}
		TileSetMetaData tileSetMetaData = tileSets["MetaDataTileSet"].metaData[tileSetID];
		if (tileSetMetaData.terrain != Tile.TerrainType.None)
		{
			if (tileMap[tileMapRow, tileMapCol] == null)
			{
				tileMap[tileMapRow, tileMapCol] = new Tile(tileMapRow, tileMapCol, tileSetMetaData.terrain);
			}
			tileMap[tileMapRow, tileMapCol].terrain = tileSetMetaData.terrain;
		}
	}
	public void ParseConnectionsLayer(XmlNode outerNode, int tileMapRow, int tileMapCol, int tileSetID)
	{
		if (tileSetID <= 0 || !tileSets["MetaDataTileSet"].metaData.ContainsKey(tileSetID))
