using UnityEngine;
public class TriggerEvent
{
	public string targetName;
	public string targetTag;
	public string targetLayerName;
	private int targetLayer = -1;
	public TriggerEvent(string newTargetName = "", string newTargetTag = "", string newTargetLayer = "")
	{
		targetName = newTargetName;
		targetTag = newTargetTag;
		targetLayerName = newTargetLayer;
		if (targetLayerName != string.Empty)
		{
			targetLayer = LayerMask.NameToLayer(targetLayerName);
		}
	}
	public bool CheckCollision(Collider2D col)
	{
		if (col == null)
		{
			return false;
		}
		if ((targetName == string.Empty || col.gameObject.name == targetName) && (targetTag == string.Empty || col.CompareTag(targetTag)) && (targetLayer == -1 || col.gameObject.layer == targetLayer))
		{
			return true;
		}
		return false;
	}
}

