	public PickupItem SpawnItem(PoolType poolType, Vector2 spawnLocation, bool randomizeSpawnLocation = true, float randomRange = 1.5f, string otherValue = "", bool useMinDist = false, bool useLifeTime = false, bool randomizeMovement = true, bool disableActivationSFX = false)
	{
