		{
		case PoolType.ItemDrop:
			(currentItem as ItemDrop).itemID = otherValue;
			break;
		case PoolType.SkillDrop:
		{
			SkillDrop skillDrop = (SkillDrop)currentItem;
			string text = otherValue;
			if (otherValue.StartsWith("New"))
			{
				skillDrop.lockedSkillSelected = true;
				text = text.Substring(3);
			}
			if (otherValue.EndsWith("Signature"))
			{
				skillDrop.isSignature = true;
				text = text.Substring(0, text.Length - 9);
			}
			if (otherValue.EndsWith("Empowered"))
			{
				skillDrop.isEmpowered = true;
				text = text.Substring(0, text.Length - 9);
			}
			skillDrop.skillID = text;
			break;
		}
		case PoolType.SoulPowerup:
			currentItem.useLifeTime = true;
			break;
		}
		currentItem.transform.position = spawnLocation;
		if (randomizeSpawnLocation)
		{
			Vector2 randomSpawnLocation = GetRandomSpawnLocation(spawnLocation, randomRange, useMinDist);
