	public Vector2 GetRandomSpawnLocation(Vector2 spawnOrigin, float range = 1.5f, bool useMinDist = false)
	{
		float num;
		float num2;
		if (useMinDist)
		{
			num = ((UnityEngine.Random.Range(0, 2) != 0) ? UnityEngine.Random.Range(1f, range) : UnityEngine.Random.Range(0f - range, -1f));
			num2 = ((UnityEngine.Random.Range(0, 2) != 0) ? UnityEngine.Random.Range(1f, range) : UnityEngine.Random.Range(0f - range, -1f));
		}
		else
		{
			num = UnityEngine.Random.Range(0f - range, range);
			num2 = UnityEngine.Random.Range(0f - range, range);
		}
		Vector2 vector = new Vector2(spawnOrigin.x + num, spawnOrigin.y + num2);
		Array.Clear(spawnLocationCheck, 0, spawnLocationCheck.Length);
		Physics2D.OverlapPointNonAlloc(vector, spawnLocationCheck);
		Collider2D[] array = spawnLocationCheck;
		foreach (Collider2D collider2D in array)
		{
			if (collider2D != null && collider2D.gameObject.layer == LayerMask.NameToLayer("Wall"))
			{
				return spawnOrigin;
			}
		}
		return vector;
	}
	public void SpawnGoldValue(int value, Vector2 spawnOrigin, bool randomizeSpawnLocation = true, float spawnRange = 1.5f)
	{
		StartCoroutine(SpawnGoldVal(value, spawnOrigin, randomizeSpawnLocation, spawnRange));
	}
	private IEnumerator SpawnGoldVal(int val, Vector2 origin, bool randomSpawnLoc = true, float range = 1.5f)
	{
		while (val > 0)
		{
			CoinType value = UnityEngine.Random.Range(0, 3) switch
			{
				0 => CoinType.Bronze, 
				1 => (val >= 5) ? CoinType.Silver : CoinType.Bronze, 
				2 => (val >= 10) ? CoinType.Gold : ((val >= 5) ? CoinType.Silver : CoinType.Bronze), 
				_ => CoinType.Bronze, 
			};
			Gold gold = GameController.itemSpawner.SpawnItem(PoolType.Gold, origin, randomSpawnLoc, range, string.Empty) as Gold;
			gold.SetValue(value);
			val -= gold.value;
		}
		yield break;
	}
